/** Inject design spec into user prompt for the coding phase. */
declare function injectDesignSpec(originalPrompt: string, spec: string): string;
/** Inject evaluation feedback for the regeneration phase. */
declare function injectFeedback(originalPrompt: string, designSpec: string, score: number, feedback: string): string;

/** Build rendering context string to inject into user prompt. */
declare function buildRenderingContext(ctx: RenderingContext): string;
